package agent

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"io"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

// TestMirrorRealArchive exercises the pinned updater against a verified archive
// generated by this repository. The large fixture is supplied explicitly.
func TestMirrorRealArchive(t *testing.T) {
	archive := os.Getenv("TELEPORT_MIRROR_TEST_ARCHIVE")
	if archive == "" {
		t.Skip("set TELEPORT_MIRROR_TEST_ARCHIVE to a generated mirror archive")
	}
	version := os.Getenv("TELEPORT_MIRROR_TEST_VERSION")
	require.NotEmpty(t, version)
	sumFile, err := os.Open(archive)
	require.NoError(t, err)
	sum := sha256.New()
	_, err = io.Copy(sum, sumFile)
	require.NoError(t, err)
	require.NoError(t, sumFile.Close())
	checksum := hex.EncodeToString(sum.Sum(nil))
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasSuffix(r.URL.Path, ".sha256") {
			_, _ = io.WriteString(w, checksum)
			return
		}
		http.ServeFile(w, r, archive)
	}))
	t.Cleanup(srv.Close)
	root := t.TempDir()
	installer := &LocalInstaller{InstallDir: root, HTTP: http.DefaultClient,
		Log: slog.Default(), Template: "{{.BaseURL}}/teleport-v{{.Version}}-linux-amd64-bin.tar.gz"}
	require.NoError(t, installer.Install(context.Background(), NewRevision(version, 0), srv.URL, false))
	for _, path := range []string{"bin/teleport", "bin/teleport-update", "bin/tsh", "bin/tctl", "bin/tbot", "lib/systemd/system/teleport.service"} {
		require.FileExists(t, filepath.Join(root, version, path))
	}
}
